using UnityEngine;

// This class calculates the aim direction from the player's root transform for stability.
public class PlayerAiming
{
    private readonly Camera _cam;
    private readonly Transform _playerTransform;

    public Vector3 AimDirection { get; private set; }
    public Vector3 AimPosition { get; private set; }

    public PlayerAiming(Camera cam, Transform playerTransform)
    {
        _cam = cam;
        _playerTransform = playerTransform;
    }

    public void Tick()
    {
        Plane groundPlane = new Plane(Vector3.up, _playerTransform.position);
        Ray ray = _cam.ScreenPointToRay(Input.mousePosition);

        if (groundPlane.Raycast(ray, out float enter))
        {
            AimPosition = ray.GetPoint(enter);
            AimDirection = (AimPosition - _playerTransform.position).normalized;
        }
    }
}

using UnityEngine;

public class PlayerShooting
{
    private readonly Transform _playerTransform;
    private readonly float _fireRate = 0.25f;
    private float _nextFireTime = 0f;

    private readonly WeaponBase _weapon;

    public PlayerShooting(Transform playerTransform, Transform firePoint, GameObject bulletPrefab)
    {
        _playerTransform = playerTransform;
        _weapon = new BulletWeapon(_playerTransform, firePoint, bulletPrefab);
    }

    public void Tick(Vector3 aimDir)
    {
        if (Input.GetMouseButton(0) && Time.time >= _nextFireTime)
        {
            _nextFireTime = Time.time + _fireRate;
            _weapon.Fire(aimDir);
        }
    }
}

