using UnityEngine;

public class PlayerAiming
{
    private readonly Camera _cam;
    private readonly Transform _aimTransform; // Będziemy obracać tę część ciała, a nie całą postać

    public Vector3 AimPosition { get; private set; }

    public PlayerAiming(Camera cam, Transform aimTransform)
    {
        _cam = cam;
        _aimTransform = aimTransform;
    }

    public void Tick()
    {
        Plane groundPlane = new Plane(Vector3.up, _aimTransform.position);
        Ray ray = _cam.ScreenPointToRay(Input.mousePosition);

        if (groundPlane.Raycast(ray, out float enter))
        {
            AimPosition = ray.GetPoint(enter);
        }
    }

