    {
        Owner = owner;
    }

    public abstract void Fire();
}

using UnityEngine;

public class BulletWeapon : WeaponBase
{
    private readonly Transform _firePoint;
    private readonly float _bulletSpeed = 25f;
    private readonly ObjectPool<Bullet> _bulletPool;

    public BulletWeapon(Transform owner, Transform firePoint, GameObject bulletPrefab, int poolSize = 20)
        : base(owner)
    {
        _firePoint = firePoint;

        Bullet bulletComp = bulletPrefab.GetComponent<Bullet>();
        if (bulletComp == null)
        {
            Debug.LogError("Bullet prefab must have a Bullet component!");
            return;
        }
        _bulletPool = new ObjectPool<Bullet>(bulletComp, poolSize);
    }

    public override void Fire()
    {
        Bullet bullet = _bulletPool.GetObject();

        bullet.transform.position = _firePoint.position;
        bullet.transform.rotation = _firePoint.rotation; // Użyj rotacji firePoint
        bullet.Init(_bulletPool);
        bullet.Fire(_firePoint.forward, _bulletSpeed); // Użyj wektora forward z firePoint
    }
}

