using UnityEngine;

// This class calculates the aim direction and position.
// It uses a specific transform (like a head or spine bone) as the origin for the aim direction vector.
public class PlayerAiming
{
    private readonly Camera _cam;
    private readonly Transform _aimOriginTransform; // The point from which aiming is calculated (e.g., the head)

    public Vector3 AimDirection { get; private set; }
    public Vector3 AimPosition { get; private set; }

    public PlayerAiming(Camera cam, Transform aimOriginTransform)
    {
        _cam = cam;
        _aimOriginTransform = aimOriginTransform;
    }

    public void Tick()
    {
        // Use a plane at the origin's height for more accurate raycasting
        Plane groundPlane = new Plane(Vector3.up, _aimOriginTransform.position);
        Ray ray = _cam.ScreenPointToRay(Input.mousePosition);

        if (groundPlane.Raycast(ray, out float enter))
        {
            AimPosition = ray.GetPoint(enter);
            // Calculate direction from the correct origin point
            AimDirection = (AimPosition - _aimOriginTransform.position).normalized;
        }
    }
}

